```js
async function getUser(id) {
  const rows = await db.query('SELECT * FROM users WHERE id = ?', [id]);
  if (!rows.length) throw new Error('Not found');
  return rows[0];
}
```

Callers use `try/catch` or `.catch()` instead of checking the `err` argument:

```js
// before
getUser(id, (err, user) => { ... });

// after
const user = await getUser(id);         // in async context
// or
getUser(id).then(user => ...).catch(err => ...);
```

This assumes `db.query` already returns a Promise. If it's still callback-based, wrap it first with `util.promisify`:

```js
const { promisify } = require('util');
const query = promisify(db.query.bind(db));
```

Then use `query(...)` in place of `db.query(...)`.
